// Builds the Sales Cheat Code scoreboard page from the Leads and Call Log tabs.
const BASE = 'https://your-n8n-instance.app.n8n.cloud/webhook';
const GAPS = [0, 2, 2, 3, 7];               // same follow up schedule as v2
const SKIP = ['closed', 'do not contact', 'dead'];
const STAGES = ['New lead', 'Contacted', 'Soft pull', 'Credit pull', 'App out', 'Package back', 'Underwriting'];
const STAGE_XP = { 'app out': 50, 'package back': 60, 'underwriting': 75 };
const XP = { followUp: 10, call: 25, closed: 150 };
const LEVELS = ['Rookie', 'Dialer', 'Closer', 'Rainmaker', 'Top Producer', 'Legend'];
const PER_LEVEL = 250;

const tz = 'America/Detroit';
const today = DateTime.now().setZone(tz).startOf('day');
const parse = s => {
  if (!s) return null;
  for (const f of ['M/d/yyyy', 'MM/dd/yyyy', 'yyyy-MM-dd', 'M/d/yy']) {
    const d = DateTime.fromFormat(String(s).trim(), f, { zone: tz });
    if (d.isValid) return d.startOf('day');
  }
  return null;
};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const low = s => String(s ?? '').trim().toLowerCase();

const leads = $('Read leads').all().map(i => i.json).filter(r => r.Name);
const calls = $('Read call log').all().map(i => i.json).filter(r => r.Lead);
const logged = ($('Open scoreboard').first().json.query || {}).logged || '';

// ---------- score ----------
let followUps = 0, stageXp = 0, closed = 0;
for (const l of leads) {
  followUps += parseInt(l.Attempts || 0, 10) || 0;
  if (low(l.Status) === 'closed') { closed++; stageXp += XP.closed; }
  else stageXp += STAGE_XP[low(l.Stage)] || 0;
}
const xp = followUps * XP.followUp + calls.length * XP.call + stageXp;
const level = Math.floor(xp / PER_LEVEL) + 1;
const title = LEVELS[Math.min(level - 1, LEVELS.length - 1)];
const into = xp % PER_LEVEL;

// ---------- streak: consecutive days with any activity ----------
const days = new Set();
leads.forEach(l => { const d = parse(l['Last Contact']); if (d) days.add(d.toISODate()); });
calls.forEach(c => { const d = parse(c.Date); if (d) days.add(d.toISODate()); });
let streak = 0, cur = days.has(today.toISODate()) ? today : today.minus({ days: 1 });
while (days.has(cur.toISODate())) { streak++; cur = cur.minus({ days: 1 }); }

// ---------- today's quest ----------
const due = [], doneToday = [];
for (const l of leads) {
  if (SKIP.includes(low(l.Status))) continue;
  const attempts = parseInt(l.Attempts || 0, 10) || 0;
  const last = parse(l['Last Contact']);
  if (last && last.equals(today)) { doneToday.push(l); continue; }
  const gap = attempts < GAPS.length ? GAPS[attempts] : 14;
  const dueDate = last ? last.plus({ days: gap }) : today;
  if (dueDate <= today) due.push({ ...l, attempts, overdue: Math.round(today.diff(dueDate, 'days').days) });
}
const order = { hot: 0, warm: 1, cold: 2 };
due.sort((a, b) => (order[low(a.Temperature)] ?? 3) - (order[low(b.Temperature)] ?? 3) || b.overdue - a.overdue);
const questTotal = due.length + doneToday.length;
const questDone = doneToday.length;

// ---------- pipeline ----------
const counts = STAGES.map(s => ({ s, n: leads.filter(l => low(l.Stage) === low(s) && !SKIP.includes(low(l.Status))).length }));
const maxN = Math.max(1, ...counts.map(c => c.n));

// ---------- badges ----------
const badges = [
  { name: 'First Contact', how: 'Log your first follow up', on: followUps >= 1 },
  { name: 'Call Analyst', how: 'Analyze a call with v3', on: calls.length >= 1 },
  { name: 'Grinder', how: 'Reach 25 follow ups', on: followUps >= 25 },
  { name: 'Hot Streak', how: '5 day activity streak', on: streak >= 5 },
  { name: 'Quest Clear', how: "Clear a day's follow ups", on: questTotal > 0 && questDone === questTotal },
  { name: 'Closer', how: 'Close a deal', on: closed >= 1 },
];

// ---------- page ----------
const tempTag = t => `<span class="tag t-${esc(low(t) || 'none')}">${esc(t || '?')}</span>`;
const dueRows = due.map(l => `
  <li class="row">
    <div class="who"><b>${esc(l.Name)}</b> ${tempTag(l.Temperature)}
      <div class="meta">${esc(l.Stage)} · attempt ${l.attempts + 1}${l.overdue > 0 ? ` · <em>${l.overdue}d overdue</em>` : ''}</div>
      ${l.Notes ? `<div class="note">${esc(l.Notes)}</div>` : ''}</div>
    <a class="btn" href="${BASE}/log-followup?name=${encodeURIComponent(l.Name)}&attempts=${l.attempts}">LOG IT<small>+${XP.followUp} XP</small></a>
  </li>`).join('') || `<li class="empty">All clear. Nothing due right now.</li>`;
const doneRows = doneToday.map(l => `<li class="done">${esc(l.Name)}</li>`).join('');
const pipe = counts.map(c => `
  <div class="stage"><span>${esc(c.s)}</span><div class="bar"><i style="width:${(c.n / maxN) * 100}%"></i></div><b>${c.n}</b></div>`).join('');
const callRows = calls.slice(-4).reverse().map(c => `
  <li class="call"><div><b>${esc(c.Lead)}</b> ${tempTag(c.Temperature)} <span class="meta">${esc(c.Date)}</span></div>
  <div class="note">${esc(c['Next Step'])}</div></li>`).join('') || `<li class="empty">No calls analyzed yet. Upload one with v3.</li>`;
const badgeHtml = badges.map(b => `<div class="badge ${b.on ? 'on' : ''}"><b>${esc(b.name)}</b><span>${b.on ? 'Unlocked' : esc(b.how)}</span></div>`).join('');

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sales Cheat Code Scoreboard</title>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Press+Start+2P&family=IBM+Plex+Mono:wght@400;600&display=swap">
<style>
:root{--bg:#0b0f1e;--panel:#141a33;--line:#2a3360;--fg:#e8ecff;--dim:#8e97c4;--gold:#ffcc4d;--green:#5cf28f;--hot:#ff5c7a;--warm:#ffab4d;--cold:#5cb8ff;
--pixel:"Press Start 2P",ui-monospace,monospace;--mono:"IBM Plex Mono",ui-monospace,Menlo,monospace}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--fg);font-family:var(--mono);font-size:14px;line-height:1.5;
background-image:linear-gradient(rgba(255,255,255,.025) 1px,transparent 1px);background-size:100% 3px}
.wrap{max-width:980px;margin:0 auto;padding:24px 16px 48px;display:grid;gap:18px}
h1{font-family:var(--pixel);font-size:clamp(16px,4vw,26px);margin:0;color:var(--gold);text-shadow:3px 3px 0 #b3401f;letter-spacing:1px}
h2{font-family:var(--pixel);font-size:11px;margin:0 0 14px;color:var(--dim);letter-spacing:1px}
.top{display:flex;flex-wrap:wrap;gap:12px 24px;align-items:end;justify-content:space-between}
.sub{color:var(--dim);font-size:12px;margin-top:8px}
.hud{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}
.panel{background:var(--panel);border:3px solid var(--line);padding:16px;min-width:0;box-shadow:4px 4px 0 #050711}
.big{font-family:var(--pixel);font-size:20px;color:var(--fg);margin:4px 0 10px}
.big small{font-size:10px;color:var(--gold);margin-left:6px}
.meter{height:14px;border:2px solid var(--line);background:#0a0d1a;position:relative}
.meter i{position:absolute;inset:0 auto 0 0;background:repeating-linear-gradient(90deg,var(--gold) 0 10px,#e0a92b 10px 12px)}
.meter.g i{background:repeating-linear-gradient(90deg,var(--green) 0 10px,#3cc46e 10px 12px)}
.cap{display:flex;justify-content:space-between;font-size:11px;color:var(--dim);margin-top:6px}
.flame{display:inline-flex;gap:4px;margin-top:2px}.flame i{width:12px;height:12px;background:var(--line)}.flame i.on{background:var(--hot);box-shadow:0 0 8px var(--hot)}
.grid{display:grid;grid-template-columns:3fr 2fr;gap:18px}
@media(max-width:760px){.grid{grid-template-columns:1fr}}
ul{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.row{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px;background:#0f1430;border:2px solid var(--line)}
.who{min-width:0}.meta{color:var(--dim);font-size:12px}.meta em{color:var(--hot);font-style:normal}
.note{font-size:12.5px;color:#c3c9ec;margin-top:4px}
.tag{font-family:var(--pixel);font-size:8px;padding:3px 5px;margin-left:6px;vertical-align:2px;border:2px solid currentColor}
.t-hot{color:var(--hot)}.t-warm{color:var(--warm)}.t-cold{color:var(--cold)}.t-none{color:var(--dim)}
.btn{flex:none;font-family:var(--pixel);font-size:10px;color:#0b0f1e;background:var(--green);padding:10px 12px;text-decoration:none;text-align:center;box-shadow:3px 3px 0 #1d7a43;display:grid;gap:6px}
.btn small{font-size:7px}.btn:hover{filter:brightness(1.1)}.btn:active{transform:translate(2px,2px);box-shadow:1px 1px 0 #1d7a43}
.btn:focus-visible{outline:3px solid var(--gold);outline-offset:2px}
.done{color:var(--dim);text-decoration:line-through;font-size:13px}
.empty{color:var(--dim);padding:8px 0}
.stage{display:grid;grid-template-columns:96px 1fr 22px;gap:10px;align-items:center;font-size:12px;margin-bottom:8px}
.stage .bar{height:12px;background:#0a0d1a;border:2px solid var(--line)}.stage .bar i{display:block;height:100%;background:var(--cold)}
.stage b{font-family:var(--pixel);font-size:10px;text-align:right}
.call{padding-bottom:10px;border-bottom:2px dashed var(--line)}.call:last-child{border:0}
.badges{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px}
.badge{border:2px dashed var(--line);padding:10px;display:grid;gap:4px;color:var(--dim)}
.badge b{font-family:var(--pixel);font-size:9px}.badge span{font-size:11px}
.badge.on{border:2px solid var(--gold);color:var(--gold);background:rgba(255,204,77,.06)}.badge.on span{color:var(--fg)}
.toast{font-family:var(--pixel);font-size:11px;background:var(--green);color:#0b0f1e;padding:12px 14px;box-shadow:4px 4px 0 #1d7a43}
.rules{color:var(--dim);font-size:12px}
@media(prefers-reduced-motion:no-preference){.toast{animation:pop .5s steps(4)}@keyframes pop{from{transform:scale(.8)}to{transform:none}}}
</style></head><body><div class="wrap">
${logged ? `<div class="toast">+${XP.followUp} XP · FOLLOW UP LOGGED: ${esc(logged)}</div>` : ''}
<div class="top"><div><h1>SALES CHEAT CODE</h1><div class="sub">Scoreboard · ${today.toFormat('cccc, LLL d')} · live from your lead sheet</div></div></div>
<div class="hud">
  <div class="panel"><h2>LEVEL</h2><div class="big">LV ${level}<small>${esc(title.toUpperCase())}</small></div>
    <div class="meter"><i style="width:${(into / PER_LEVEL) * 100}%"></i></div><div class="cap"><span>${xp} XP</span><span>${PER_LEVEL - into} to LV ${level + 1}</span></div></div>
  <div class="panel"><h2>DAILY QUEST</h2><div class="big">${questDone}/${questTotal}<small>FOLLOW UPS</small></div>
    <div class="meter g"><i style="width:${questTotal ? (questDone / questTotal) * 100 : 100}%"></i></div><div class="cap"><span>Clear the list</span><span>${questTotal - questDone} left</span></div></div>
  <div class="panel"><h2>STREAK</h2><div class="big">${streak}<small>DAY${streak === 1 ? '' : 'S'}</small></div>
    <div class="flame">${Array.from({ length: 7 }, (_, i) => `<i class="${i < streak ? 'on' : ''}"></i>`).join('')}</div><div class="cap"><span>Any follow up or call counts</span></div></div>
</div>
<div class="grid">
  <div class="panel"><h2>DUE TODAY · HOTTEST FIRST</h2><ul>${dueRows}${doneRows}</ul></div>
  <div style="display:grid;gap:18px;align-content:start">
    <div class="panel"><h2>PIPELINE</h2>${pipe}</div>
    <div class="panel"><h2>RECENT CALLS · +${XP.call} XP EACH</h2><ul>${callRows}</ul></div>
  </div>
</div>
<div class="panel"><h2>BADGES</h2><div class="badges">${badgeHtml}</div></div>
<div class="rules">XP: follow up +${XP.followUp} · call analyzed +${XP.call} · app out +50 · package back +60 · underwriting +75 · closed +${XP.closed}. Every ${PER_LEVEL} XP is a new level.</div>
</div></body></html>`;

return [{ json: { html } }];
